def algorithm(func, dim, lb, ub, budget, rng):
    def clip(c):
        return np.clip(c, lb, ub)

    pop_size = 50
    sigma = 0.5
    tol = 1e-6
    temp = 10000
    alpha = 0.99

    x = rng.uniform(lb, ub, size=(pop_size, dim))
    y = np.copy(x)
    f = func(x)

    for i in range(budget):
        indices = rng.choice(pop_size, size=3, replace=False)
        u = x[indices]
        v = 1 / (1 + np.exp(-np.random.uniform(-4, 4)))
        w = u[:, np.newaxis] + sigma * rng.normal(size=(pop_size, dim))
        z = clip(w)

        for j in range(pop_size):
            temp *= alpha
            if f[j] > func(z[j]):
                x[j] = z[j]
                y[j] = z[j]
                f[j] = func(z[j])
            elif np.random.uniform() < np.exp(-(f[j] - func(z[j])) / temp):
                x[j] = z[j]
                y[j] = z[j]
                f[j] = func(z[j])

        if i % 100 == 0:
            print(f'Iteration {i}: Best function value = {np.min(f)}')

    return np.argmin(f)

def algorithm(func, dim, lb, ub, budget, rng):
    n = len(rng.uniform(lb, ub, size=(dim,)))
    best_x = n.copy()
    best_f = func(n)

    def acceptance_probability(new_f, current_f, T):
        return np.exp((current_f - new_f) / T)

    T = 1.0
    while budget > 0:
        x_new = n + rng.normal(size=(dim,))

        # Clip to bounds
        for i in range(dim):
            if x_new[i] < lb or x_new[i] > ub:
                x_new[i] = np.clip(x_new[i], lb, ub)

        f_new = func(x_new)

        if f_new < best_f:
            best_x = x_new.copy()
            best_f = f_new

        if rng.random() < min(1.0, acceptance_probability(best_f, f_new, T)):
            n = x_new.copy()

        budget -= 1
        T *= 0.99  # cooling schedule

        if np.isnan(func(n)):
            return best_x

    return best_x

